{
#pragma HLS INLINE OFF
    if (flag){
        int start_idx = store_idx * NUM_PT_IN_BUFFER / WIDTH_FACTOR;
        STORE_TILE: for (int i(0); i < NUM_PT_IN_BUFFER/WIDTH_FACTOR; ++i){
        #pragma HLS PIPELINE II=1
            distance[start_idx+i] = local_distance[i];
        }
    }
}

